{
  "technical_and_design_decisions": [
    "RabbitMQ resource cleanup (U1) will be implemented by extending the MessageBus interface with resource management methods (e.g., cleanConsumer/cleanProducer) and adding a --clean flag to the stream destroy shell command and REST controller.",
    "Error notification channels (U2) will leverage Spring Integration's errorChannel abstraction per module/stream deployment, routing exceptions to accessible tap channels.",
    "Security architecture (U3) will utilize Spring Security integrated into Spring XD REST endpoints, supporting configurable authentication methods for CLI Shell and Admin UI.",
    "Documentation (U4) will systematically detail all expression variables (${xd.stream.name}, ${xd.job.name}, ${xd.container.*}) in public documentation.",
    "MVC-aware HTTP source module (U5) will embed Tomcat/Jetty, utilizing Spring MVC controllers to support rich content-type negotiation, full header mapping, and security filters.",
    "Status propagation (U6) will implement client-side polling in the DSL Shell/UI along with a server-side event listener bus notifying UI clients of module and container state transitions.",
    "SFTP source module (U7) will wrap Spring Integration SFTP Inbound Channel Adapter with configurable remote/local directory options and test container support.",
    "Elasticsearch sink module (U8) will utilize Spring Data Elasticsearch / Client to support batch indexing and dynamic mapping from Spring XD payload structures."
  ],
  "assumptions": [
    "Development is performed by a senior Java/Spring software engineer with expertise in Spring XD, Spring Integration, and Spring Security.",
    "Integration test environments can run embedded/containerized versions of RabbitMQ, SFTP servers, and Elasticsearch.",
    "No major architectural breaking changes are required for existing Spring XD message buses beyond extending cleaner interfaces.",
    "All effort estimates represent pure developer workdays excluding external organizational delays."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Architecture, Setup & Integration Test Infrastructure",
      "activity_description": "Initial environment setup, baseline architecture analysis, and creation of test container harnesses for RabbitMQ, SFTP, and Elasticsearch integration tests.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "U1: Stream Queue/Topic Cleanup on Stream Destroy",
      "activity_description": "Implement optional `--clean` flag in Shell CLI, add REST API parameters, and extend MessageBus/RabbitAdmin to perform consumer/binding/queue cleanup upon stream destroy.",
      "most_likely_effort": 4.5
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "U2: Module Exception & Error Channel Notification",
      "activity_description": "Expose module exception channels, wire stream-level and module-level error channels, and allow tapping into failure streams.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "U3: REST API & System Security Spike/Implementation",
      "activity_description": "Research Spring Security integration for XD REST endpoints, implement authentication configuration support, and integrate authentication with DSL Shell and Admin UI.",
      "most_likely_effort": 5.0
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "U4: System Variable Property Documentation",
      "activity_description": "Audit and document available runtime expression variables such as `${xd.stream.name}`, `${xd.job.name}`, and `${xd.container.*}` in user guide.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "U5: OOTB MVC-Aware HTTP Source Module",
      "activity_description": "Develop dedicated HTTP source module with embedded web container, full HTTP header mapping, content-type negotiation, and Spring Security compatibility.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "U6: Client-Side Polling & Server-Side Event Notifications",
      "activity_description": "Implement client polling mechanisms for status checks and build server-to-client event propagation for job and stream status changes.",
      "most_likely_effort": 4.5
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "U7: SFTP Source Module Implementation",
      "activity_description": "Build OOTB SFTP source module wrapping Spring Integration SFTP adapters with configurable credentials, remote paths, and automated integration tests.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "U8: Native Elasticsearch Sink Module Implementation",
      "activity_description": "Build OOTB Elasticsearch sink module allowing real-time data ingestion, index configuration, and dynamic document mapping.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "End-to-End System Testing & Verification",
      "activity_description": "Perform overall system integration testing across all stories (clean-up, security, error channels, HTTP/SFTP/Elasticsearch modules, and status events).",
      "most_likely_effort": 4.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 37.0
  }
}

